sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var prefs = api.context.session.user.preferences;
  for (var i = 0; i < prefs.length; i++) {
    var pref = prefs[i];
    if (pref.name == 'workspace.showRibbon' && pref.value == 'false') {
      return true;
    }
  }
	return false;
}
